from __future__ import annotations

from datetime import tzinfo
from typing import TYPE_CHECKING
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from django.conf import settings
from django.core.exceptions import ObjectDoesNotExist

if TYPE_CHECKING:
    from django.contrib.auth.models import User


def _settings_default_timezone() -> ZoneInfo:
    return ZoneInfo(getattr(settings, "TIME_ZONE", "UTC"))


def resolve_user_timezone(
    user: User | None,
    *,
    fallback: tzinfo | None = None,
) -> tzinfo:
    """Resolve a user's profile timezone, falling back to `fallback`.

    Falls back when: user is None, profile is missing, profile.timezone is
    blank, or the timezone name is unknown to ZoneInfo. `fallback` defaults
    to `settings.TIME_ZONE`.
    """
    resolved_fallback = fallback if fallback is not None else _settings_default_timezone()
    if user is None:
        return resolved_fallback
    try:
        timezone_name = user.profile.timezone
    except (AttributeError, ObjectDoesNotExist):
        return resolved_fallback
    if not timezone_name:
        return resolved_fallback
    try:
        return ZoneInfo(timezone_name)
    except ZoneInfoNotFoundError:
        return resolved_fallback

