            "title": program.title,
            "notes": program.notes,
            "frequency": program.frequency,
            "assignment_mode": program.assignment_mode,
            "assigned_to": self._serialize_user_summary(program.assigned_to),
            "rotation_member_ids": [
                str(member_id) for member_id in program.rotation_member_ids
            ],
            "current_rotation_index": program.current_rotation_index,
            "rotation_anchor_date": (
