from __future__ import annotations

import re
from datetime import datetime, timedelta, tzinfo
from typing import TYPE_CHECKING
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from django.core.exceptions import ObjectDoesNotExist
from django.utils import timezone

if TYPE_CHECKING:
    from django.contrib.auth.models import User

    from .models import Event

MAX_ARRIVE_BY_MINUTES = 12 * 60

_ARRIVE_BY_RELATIVE_PATTERNS = (
    re.compile(
        r"^(?:arrival|arrive|be there|check in)(?:\s*[:\-]\s*|\s+)"
        r"(?P<minutes>\d{1,3})\s*(?:minutes?|mins?|min)\s*"
        r"(?:in advance|early|before|prior|ahead)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"^(?:arrival|arrive|be there|check in)\s+(?:by\s+)?"
        r"(?P<minutes>\d{1,3})\s*(?:minutes?|mins?|min)\s*"
        r"(?:in advance|early|before|prior|ahead)\b",
        re.IGNORECASE,
    ),
)

_ARRIVE_BY_ABSOLUTE_PATTERN = re.compile(
    r"^(?:arrive|arrival|be there|check in)"
    # Allow "Arrival Time: 3:45 PM" style exports from TeamSnap etc.
    r"(?:\s+time)?"
    r"(?:\s+(?:by|at))?"
    r"(?:\s*[:\-]\s*|\s+)"
    r"(?P<hour>\d{1,2})"
    r"(?::(?P<minute>\d{2}))?"
    r"\s*(?P<meridiem>am|pm)?\b",
    re.IGNORECASE,
)


def _normalize_arrive_by_line(line: str) -> str:
    # Strip surrounding parentheses/brackets as well as common punctuation so
    # wrapped exports like "(Arrival Time: 3:45 PM (Eastern Time (US & Canada)))"
    # expose the leading keyword to the prefix check below.
    return re.sub(r"\s+", " ", line.strip().strip(".,;:-()[]"))


def _extract_candidate_lines(description: str) -> list[str]:
    candidates: list[str] = []
    for raw_line in description.splitlines():
        normalized = _normalize_arrive_by_line(raw_line)
        if not normalized:
            continue
        lowered = normalized.lower()
        if any(
            lowered.startswith(prefix)
            for prefix in ("arrive", "arrival", "be there", "check in")
        ):
            candidates.append(normalized)
    return candidates


def _parse_relative_minutes(line: str) -> int | None:
    for pattern in _ARRIVE_BY_RELATIVE_PATTERNS:
        match = pattern.match(line)
        if not match:
            continue

        minutes = int(match.group("minutes"))
        if 0 < minutes <= MAX_ARRIVE_BY_MINUTES:
            return minutes
    return None


def _event_start_in_timezone(
    event_start: datetime,
    event_timezone: tzinfo | None,
) -> datetime:
    if event_timezone is None:
        return event_start

    if timezone.is_naive(event_start):
        return timezone.make_aware(event_start, event_timezone)

    return event_start.astimezone(event_timezone)


def _candidate_absolute_datetimes(
    *,
    event_start: datetime,
    hour: int,
    minute: int,
    meridiem: str | None,
) -> list[datetime]:
    base = event_start.replace(
        second=0,
        microsecond=0,
    )

    if meridiem:
        normalized_hour = hour % 12
        if meridiem.lower() == "pm":
            normalized_hour += 12
        return [base.replace(hour=normalized_hour, minute=minute)]

    # Hours 13-23 are unambiguous 24-hour time; return a single candidate
    if hour >= 13:
        return [base.replace(hour=hour, minute=minute)]

    candidates: list[datetime] = []
    for candidate_hour in {hour % 12, (hour % 12) + 12}:
        candidates.append(base.replace(hour=candidate_hour, minute=minute))
    return sorted(candidates)


def _parse_absolute_minutes(
    line: str,
    event_start: datetime,
    event_timezone: tzinfo | None,
) -> int | None:
    match = _ARRIVE_BY_ABSOLUTE_PATTERN.match(line)
    if not match:
        return None

    hour = int(match.group("hour"))
    minute = int(match.group("minute") or "0")
    meridiem = match.group("meridiem")

    if hour > 23 or minute > 59:
        return None

    comparison_start = _event_start_in_timezone(event_start, event_timezone)
    candidate_offsets: set[int] = set()
    for candidate in _candidate_absolute_datetimes(
        event_start=comparison_start,
        hour=hour,
        minute=minute,
        meridiem=meridiem,
    ):
        offset_minutes = int((comparison_start - candidate).total_seconds() // 60)
        if 0 < offset_minutes <= MAX_ARRIVE_BY_MINUTES:
            candidate_offsets.add(offset_minutes)

    if len(candidate_offsets) != 1:
        return None

    return next(iter(candidate_offsets))


def parse_arrive_by_minutes_before_start(
    description: str | None,
    event_start: datetime | None,
    *,
    event_timezone: tzinfo | None = None,
) -> int | None:
    if not description or event_start is None:
        return None

    matches: set[int] = set()
    for line in _extract_candidate_lines(description):
        relative_minutes = _parse_relative_minutes(line)
        if relative_minutes is not None:
            matches.add(relative_minutes)
            continue

        absolute_minutes = _parse_absolute_minutes(
            line,
            event_start,
            event_timezone,
        )
        if absolute_minutes is not None:
            matches.add(absolute_minutes)

    if len(matches) != 1:
        return None

    return next(iter(matches))


def get_arrive_by_event_timezone(event: Event) -> tzinfo:
    try:
        profile = getattr(getattr(event, "creator", None), "profile", None)
    except ObjectDoesNotExist:
        profile = None

    timezone_name = getattr(profile, "timezone", None)
    if timezone_name:
        try:
            return ZoneInfo(timezone_name)
        except ZoneInfoNotFoundError:
            pass

    return timezone.get_current_timezone()


def get_arrive_by_time(event: Event) -> datetime | None:
    minutes_before_start = getattr(event, "arrive_by_minutes_before_start", None)
    start_time = getattr(event, "start_time", None)

    if (
        getattr(event, "arrive_by_mode", None) == "OFF"
        or minutes_before_start is None
        or minutes_before_start <= 0
        or start_time is None
    ):
        return None

    return start_time - timedelta(minutes=minutes_before_start)


def can_user_view_arrive_by(
    event: Event,
    user: User | None,
    *,
    direct_family_ids: set[object] | None = None,
) -> bool:
    if not user or not getattr(user, "is_authenticated", False):
        return False

    family_group = getattr(event, "family_group", None)
    if family_group is None:
        return False

    if getattr(getattr(family_group, "group_type", None), "type", None) != "IMMEDIATE":
        return False

    if direct_family_ids is not None:
        return family_group.id in direct_family_ids

    from users.models import FamilyMembership

    return FamilyMembership.objects.filter(
        user=user,
        family=family_group,
        is_active=True,
    ).exists()


def get_arrive_by_payload(
    event: Event,
    *,
    user: User | None = None,
    direct_family_ids: set[object] | None = None,
    skip_access_check: bool = False,
) -> dict[str, object] | None:
    if not skip_access_check:
        if user is None or not can_user_view_arrive_by(
            event,
            user,
            direct_family_ids=direct_family_ids,
        ):
            return None

    arrive_by_time = get_arrive_by_time(event)
    if arrive_by_time is None:
        return None

    minutes_before_start = getattr(event, "arrive_by_minutes_before_start", None)
    if minutes_before_start is None:
        return None

    return {
        "time": arrive_by_time.isoformat(),
        "minutes_before_start": minutes_before_start,
        "source": getattr(event, "arrive_by_mode", "AUTO"),
    }


def resolve_reminder_anchor_kind(
    event: Event,
    user: User | None,
    *,
    direct_family_ids: set[object] | None = None,
) -> str:
    if get_arrive_by_time(event) is None:
        return "START"

    if can_user_view_arrive_by(
        event,
        user,
        direct_family_ids=direct_family_ids,
    ):
        return "ARRIVE_BY"

    return "START"

